using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// Configure the OpenAI chat client with tool support
var openAiClient = new OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable."));

IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.Search),
        AIFunctionFactory.Create(NotesTool.AddNote),
        AIFunctionFactory.Create(NotesTool.GetNotes),
    ]
};

// Prompt the user for a research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries).
        2. Taking notes on key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a well-structured summary.

        Always take notes as you find information, then compile them into a final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, tools);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// --- Tool Definitions ---

/// <summary>Simulates web search by returning placeholder results for demonstration.</summary>
static class WebSearchTool
{
    [Description("Searches the web for the given query and returns relevant results.")]
    public static string Search([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        // In a real application, this would call a search API (e.g., Bing Search).
        // Returning simulated results for demonstration purposes.
        return $"""
            Search results for "{query}":
            1. "{query}" - Overview article covering key concepts and recent developments.
               Snippet: This topic encompasses several important aspects including historical context,
               current state of the art, and future directions.
            2. "Recent advances in {query}" - Academic paper (2025)
               Snippet: Recent research has shown significant progress in this area, with new
               methodologies emerging that improve upon previous approaches.
            3. "{query} practical applications" - Industry report
               Snippet: Organizations are increasingly adopting these approaches, with measurable
               improvements in efficiency and effectiveness reported across multiple sectors.
            """;
    }
}

/// <summary>A simple in-memory note-taking tool for the agent.</summary>
static class NotesTool
{
    private static readonly List<string> _notes = [];

    [Description("Adds a research note. Use this to record key findings during research.")]
    public static string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You have {_notes.Count} note(s) total.";
    }

    [Description("Retrieves all research notes taken so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

